-- The private RSVP link can reveal its household attendance pass.
-- The attendance pass never exposes the RSVP editing token.
create or replace function public.resident_rsvp(p_code uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('society',jsonb_build_object('name',soc.name,'logo_url',soc.logo_url,'theme_color',soc.theme_color),'festival',f.name,'flat',fl.block||'–'||fl.flat_number,'attendance_code',e.attendance_code,'eligible',private.fixed_paid(e.id),'maximum',jsonb_array_length(e.members),'phone_hint',right(e.contact_phone,4),'days',coalesce((select jsonb_agg(jsonb_build_object('date',d.service_date,'label',d.label,'attendees',coalesce(r.attendees,jsonb_array_length(e.members)),'version',coalesce(r.version,0),'open',d.service_date>=(now() at time zone soc.timezone)::date and exists(select 1 from public.meal_services s where s.festival_id=f.id and s.service_date=d.service_date and s.coverage<>'not_served' and not s.attendance_locked and (s.booking_cutoff is null or now()<s.booking_cutoff))) order by d.day_number) from public.festival_days d left join public.resident_rsvps r on r.enrollment_id=e.id and r.service_date=d.service_date where d.festival_id=f.id),'[]'))
 from public.flat_enrollments e join public.festivals f on f.id=e.festival_id join public.flats fl on fl.id=e.flat_id join public.societies soc on soc.id=f.society_id where e.rsvp_code=p_code and e.contact_phone is not null;
$$;
